X = {}

X["iptv-glossary-for-beginners"] = [
 ("How to use this glossary",["You do not need to memorise any of this. When support asks a question such as which player app you use, or what your bitrate looks like, you can look the word up and answer in a sentence. The terms you will meet most often in practice are player app, buffering, resolution and simultaneous streams.","If you only learn one idea, make it this: delivery has several links, namely the provider, the internet, your router and your device. Almost every word above describes a problem or a feature in one of those links."])]

X["what-you-need-to-start-iptv"] = [
 ("A realistic example",["Imagine a household with a four year old smart TV, a Wi-Fi router in the hall and a phone. The sensible start is: confirm the TV model with support, move the router or add a cable if the TV is far away, install the player on the TV and keep the phone as the backup screen. Total extra spend might be nothing at all.","Compare that with a household whose TV is ten years old and has no app store. They would add a streaming stick on HDMI first, and only then choose a plan. The order matters: sort out the screen before you pay."]),
 ("Common first mistakes",[("ul",["Paying before confirming the device.","Testing at lunchtime only.","Typing sign-in details instead of pasting them.","Leaving the router in a cupboard.","Assuming a speed test result guarantees smooth live television."])])]

X["iptv-myths-explained"] = [
 ("\"A VPN fixes everything\"",["A VPN can add privacy, but it adds distance and processing, so it can slow a stream as easily as help it. It does not repair a weak Wi-Fi signal and does not change what you are entitled to watch."]),
 ("\"More channels means a better service\"",["Large numbers look impressive, but what matters is whether the channels you actually watch are present, stable and easy to find. A long list can even be harder to use without favourites. See {post:favourites-and-categories-in-iptv-apps}."]),
 ("The honest way to check any claim",["Treat every claim as a question to test. Request a trial, test at your normal viewing time, and ask support something specific. How a provider answers tells you as much as any feature list."])]

X["simple-iptv-setup-for-older-viewers"] = [
 ("A suggested first session",["Set aside thirty minutes with no pressure. Plug in the device, connect it to the TV and the Wi-Fi, install the app, sign in and watch one channel. Stop there. Add favourites another day. Doing too much in one go is the main reason people feel it is complicated.","If you are helping a relative, resist the urge to take the remote and do it for them. Let them press the buttons while you explain each step. They will remember it far better."]),
 ("Safety for new users",["Remind anyone new to streaming that nobody from a provider will ask for their bank password or a code sent by text. If a message pressures them to act quickly, they should stop and ask you first. See {post:iptv-scams-and-safe-payment}."])]

X["watch-iptv-without-a-smart-tv"] = [
 ("What it costs in practice",["A basic streaming stick is usually inexpensive and often cheaper than a month of many subscriptions. A box with an Ethernet port costs more but gives a steadier connection. Spend more only if your Wi-Fi is weak or you want the extra storage.","Whichever you choose, buy from a seller with a returns policy. If the device is slow with your player, you can send it back."]),
 ("Picture and sound on older sets",["Older HD ready TVs show 720p, so there is no benefit in paying for a 4K stick. If your TV has no HDMI sound output to a speaker, check the audio connection before you buy. A quick look at the sockets on the back of the set answers most of these questions."])]

X["how-to-install-an-iptv-app-safely"] = [
 ("A five minute safety routine",["Before you press install, open the listing, read the three most recent reviews and look at the developer's other apps. Reviews that mention hidden charges, constant adverts or the app stopping working are a warning. Reviews from a long time ago may no longer reflect the current version.","After installing, deny any permission that is unrelated to video, such as contacts or location. Most apps work fine without them."]),
 ("If you already installed something doubtful",["Uninstall it, restart the device and change any password you typed into it. Then run a security scan on a phone or computer, or reset a streaming stick if it behaves oddly. Tell support what happened so that they can advise."])]

X["first-time-iptv-setup-checklist"] = [
 ("Why testing at the right time matters",["A service that runs well at lunchtime may struggle at eight in the evening, when your area and your own household are busiest. Test at that time, and test the content you actually watch rather than a single channel.","Write down what you see. If a channel pauses, note the channel and the time. Specific notes turn a vague complaint into a problem that support can investigate."]),
 ("After a successful test",["Set up favourites, tidy the categories and keep your details somewhere private. Then pick your plan length with {post:iptv-subscription-length-guide} in mind."])]

X["iptv-on-two-tvs"] = [
 ("A sensible layout",["Put the router in a central place and connect the main living room device with a cable if possible. Use the stronger Wi-Fi band for the second room and move it nearer the router if it struggles. If one TV is far away, a mesh node or a wired link makes more difference than a faster plan.","If the two TVs are rarely used together, you may not need a plan with several streams. Think about your busiest evening, not the average one."]),
 ("Common problem: one TV works, the other does not",["If a second sign-in fails, the likely cause is the stream limit. Close the app on the first device and try again. If it then works, you have found the limit. See {post:iptv-wont-sign-in}."])]

X["move-iptv-to-a-new-device"] = [
 ("A short moving checklist",[("ul",["Check the new device with support first.","Update the new device before installing anything.","Install the player and sign in.","Test for an evening.","Sign out and uninstall on the old device when you are happy."])]),
 ("Why not delete the old setup straight away",["Keep the old device working until the new one has passed a full evening. If something goes wrong, you can fall back immediately. Many people discover a missing feature only after a few days."])]

X["reinstall-iptv-app"] = [
 ("What a reinstall does and does not fix",["It clears a damaged install, old settings and cached data. It does not fix a weak connection, an expired subscription or a device that is too slow. If the same problem returns within hours, look at the network and the device instead.","Always reinstall the same app from the same store. Installing an unofficial copy to see if it works is the quickest way to create a new problem."]),
 ("Before you start",["Write down the settings you have changed, such as favourites and parental controls, because they may need recreating. Keep your sign-in details to hand."])]

X["iptv-on-samsung-tv"] = [
 ("If the app is not available",["Do not be tempted to use workarounds from unknown websites. A streaming stick on an HDMI port is a safe route, because the TV then simply displays the stick. Put the stick on a port that supports the best picture, usually marked on the back of the TV.","Check the Wi-Fi band the TV connects to. Many TVs default to the more crowded 2.4 GHz band even when 5 GHz is available."]),
 ("Cleaning up",["Remove apps you do not use, and turn off settings that start apps automatically at power on if the TV feels slow."])]

X["iptv-on-lg-tv"] = [
 ("Sound and picture settings",["LG sets offer several picture modes. For sport, try a standard or sport mode and compare it with the default. If audio goes silent on certain channels, check the sound output format in the TV settings and switch from automatic to PCM or stereo for a test.","If you use an external soundbar, connect through the correct HDMI port and make sure the TV passes the audio through. See {post:iptv-no-audio-or-out-of-sync}."]),
 ("Keep it healthy",["Restart the TV fully every few weeks. Standby does not always clear memory."])]

X["iptv-on-nvidia-shield"] = [
 ("Settings worth checking",["In the display settings, match the resolution to your TV. If your TV supports higher refresh rates, ensure that the device is not forcing a lower one. Use the network settings to confirm that Ethernet is active, as it can be easy to leave the box on Wi-Fi after a cable is plugged in.","The Shield can also run several apps at once. Close apps you are not using so that the player has memory to itself."])]

X["iptv-on-chromecast-with-google-tv"] = [
 ("Practical tips",["Use the supplied power adapter rather than a TV USB port, because under-powered devices can restart. If the device feels slow, run a restart from the settings menu and remove unused apps.","If your remote does not respond, check the batteries and re-pair it by holding the buttons shown on the screen. Many perceived freezes are actually remote problems."])]

X["iptv-on-roku"] = [
 ("How to ask support properly",["Send your exact Roku model, which you will find in the settings under System and About, and the software version. Mention that you have not installed anything yet. Support can then say whether a supported option exists or suggest another device.","If your Roku is not suitable, switching to a different stick is often cheaper than trying to force it to work."])]

X["iptv-on-xbox"] = [
 ("When a console is a good choice",["If you already have the console connected and an app is available that works well, it can be a convenient extra screen. The console is powerful enough for smooth video, and its wired port is a plus.","Remember that consoles use more electricity than a stick. For daily television, a stick is usually the more economical device."])]

X["iptv-on-playstation"] = [
 ("Be careful with advice online",["Guides that promise to make any console run any app often rely on unofficial methods. These can break with updates, create security risks or breach the console's terms. Stick to what the official store offers.","If you are unsure, send support your console model and ask whether a supported app exists."])]

X["iptv-on-android-tv-boxes"] = [
 ("Questions to ask a seller",[("ul",["Which Android TV or Google TV version does it run, and is it certified?","Does it receive security updates?","What is the returns policy?","Does it have Ethernet and how fast?","Is the storage fixed or can it be expanded?"])]),
 ("Price and value",["Do not buy on price alone. A slightly more expensive device with proper updates will serve you for years, while a very cheap one may be slow after a few months."])]

X["iptv-on-chromebook"] = [
 ("Practical advice",["Make sure your Chromebook is up to date and has free storage. If you use a browser based sign-in, keep the tab on its own, as many tabs compete for the limited memory. Plug in for long viewing, because video decoding drains the battery quickly.","If your model cannot install the app you need, using a phone or a stick on the TV is often simpler than fighting the limits of the laptop."])]

X["firestick-vs-android-box-for-iptv"] = [
 ("A quick decision guide",[("ul",["Strong Wi-Fi next to the TV and a tight budget: a Fire TV stick.","TV far from the router and a cable available: a good Android TV box.","Several apps and downloads: more storage points to a box.","Travelling with it: a stick fits in a pocket."])]),
 ("Whichever you choose",["Test it with a trial before committing to a long plan, and keep the packaging until you are sure."])]

X["iptv-player-comparison-checklist"] = [
 ("How to score the apps",["Give each app a mark out of five for start time, guide readability, channel switching speed, stability and ease of use. Keep a short note of any crashes. After a week, add up the marks. The winner is rarely the app with the most features. It is usually the one that never gets in your way.","Ask the people you live with to try it too. A player that suits you but confuses everyone else will not last."])]

X["parental-controls-in-iptv-apps"] = [
 ("A practical setup",["Choose a four digit PIN that is not a birthday. Lock any category you do not want children to open, and test it by trying to open that category yourself. Remember that a lock inside the app does not stop a child switching to another app, so also use the device's own controls.","Review the setup every few months, because app updates can reset settings."])]

X["favourites-and-categories-in-iptv-apps"] = [
 ("Make a one page plan",["Write down the channels you open every week and group them: news, sport, films, family. Put the most used at the top. This takes ten minutes and saves time every evening.","If more than one person uses the app, create separate favourites lists if the app allows it, so nobody has to scroll through someone else's choices."])]

X["catch-up-and-recording-explained"] = [
 ("How to test either feature",["During your trial, pick a channel you care about and look for a back arrow or a past programmes option in the guide. Try to play something that aired earlier today. If you can, try a recording of a short programme and play it back the next day.","Note how long programmes stay available. A window of a day is very different from a week."])]

X["subtitles-in-iptv-apps"] = [
 ("Making text readable",["If subtitles are too small, look for text size and background options in the app or in the TV's accessibility menu. White text on a dark box is usually the most readable. Some TVs apply their own subtitle settings, which can override the app's.","If there is no subtitle option at all, check whether the stream is the issue by trying a channel that normally has them."])]

X["iptv-app-cache-and-storage"] = [
 ("A monthly routine",["Once a month, clear the player's cache, remove one or two unused apps and restart the device. It takes two minutes and prevents most slow downs. Devices with very little storage may need this more often, and if you are constantly short of space a model with more storage is worth considering.","Do not clear data unless you have your sign-in details, because it signs you out."])]
